use std::collections::HashMap;struct ValidWordAbbr{m:HashMap<String,String>}impl ValidWordAbbr{fn ab(s:&str)->String{if s.len()<=2{s.into()}else{format!("{}{}{}",s.chars().next().unwrap(),s.len()-2,s.chars().last().unwrap())}}fn new(d:Vec<String>)->Self{let mut m=HashMap::new();for s in d{let k=Self::ab(&s);if let Some(v)=m.get(&k){if v!=&s{m.insert(k,"#".into());}}else{m.insert(k,s);}}Self{m}}fn is_unique(&self,w:String)->bool{let k=Self::ab(&w);self.m.get(&k).map(|x|x==&w).unwrap_or(true)}}
